update public.products set description='Dry black-eyed white beans are a Nigerian staple cowpea with pale seeds and a distinctive dark eye, suitable for beans porridge, rice and beans, Moi Moi, Akara and other bean-based meals.', handling_protocols=array['Sort before cooking and remove stones, damaged seeds, insects and other foreign material.','Rinse thoroughly with clean water before preparation; soaking may be used to shorten cooking time.','Cook thoroughly until the beans are fully tender.']::text[], storage_tips=array['Store completely dry beans in a clean airtight or hermetic food-safe container in a cool, dry and dark location.','Protect from moisture, insects and rodents; hermetic storage is preferred for bulk quantities.','For best quality, use within about 6–12 months when dry, sealed and insect-free.','Discard beans that become moldy, damp or musty-smelling, severely infested or otherwise visibly deteriorated.']::text[] where name='Beans (Black-Eyed/White)' and category_id=(select id from public.product_categories where name='Tubers & Legumes');
update public.products set description='Drum beans are a Nigerian market type of dry brown beans used for beans porridge, rice and beans, Moi Moi, Akara and other traditional bean dishes.', handling_protocols=array['Sort carefully before cooking to remove stones, damaged beans, insects and foreign material.','Rinse thoroughly and soak where desired to shorten cooking time.','Cook fully until tender before eating.']::text[], storage_tips=array['Keep completely dry in an airtight or hermetic food-safe container.','Store in a cool, dark place away from humidity, heat, insects and rodents.','For best quality, use within about 6–12 months when properly dried and sealed.','Discard beans that become moldy, damp or musty-smelling, heavily insect-damaged or otherwise off-smelling.']::text[] where name='Beans (Drum)' and category_id=(select id from public.product_categories where name='Tubers & Legumes');
update public.products set description='Pelebe beans are a Nigerian market type of dry beans suitable for beans porridge, rice and beans, Akara, Moi Moi and other bean-based dishes.', handling_protocols=array['Sort before use and remove stones, insect-damaged seeds and foreign material.','Rinse well under clean water before cooking.','Soak where desired, then cook thoroughly until fully tender.']::text[], storage_tips=array['Store dry Pelebe beans in an airtight or hermetic food-safe container in a cool, dark and dry location.','Protect against moisture, rodents and insects, especially cowpea weevils.','For best quality, use within about 6–12 months when properly dry and sealed.','Discard beans that become moldy, damp-smelling, severely infested or otherwise rancid/off-smelling.']::text[] where name='Pelebe Beans' and category_id=(select id from public.product_categories where name='Tubers & Legumes');;
